                p.push(`${at}: preset "${f.preset}" is not one of ${MEASURED.preset.join(', ')}`);
            if (f.numberFormat !== undefined && !MEASURED.numberFormat.includes(f.numberFormat))
                p.push(`${at}: numberFormat "${f.numberFormat}" is not one of ${MEASURED.numberFormat.join(', ')}`);
            if (f.dateFormat !== undefined && !MEASURED.dateFormat.includes(f.dateFormat))
                p.push(`${at}: dateFormat "${f.dateFormat}" is not one of ${MEASURED.dateFormat.join(', ')}`);
